    <text x="668" y="44" text-anchor="end" font-family="system-ui, -apple-system, sans-serif" font-size="18" font-weight="600" fill="${color}" opacity="0.9">${countText}条评论 ›</text>
    <line x1="28" y1="58" x2="672" y2="58" stroke="${color}" stroke-width="0.3" opacity="0.35"/>
    <text x="350" y="110" text-anchor="middle" font-family="system-ui, -apple-system, sans-serif" font-size="16" fill="${color}" opacity="0.55">还没有评论，快来抢沙发吧~</text>
</svg>`;

        var encodedSvg = java.base64Encode(svg);
        var jsFunction = 'showQDCmt';
        var date = String(Date.now()).match(/(\d{6}$)/)[1];
        var baseData = `data:image/svg+xml;base64,${encodedSvg},{'${isModifiedVersion ? 'click' : 'js'}':'${jsFunction}("${bid}","${cid}","benzhang","${date}")','style':'FULL'}`;
        return '\n' + `<img src="${baseData}">`;
    }

    let headerHeight = 100;
    let cardHeight = 130;
    let cardGap = 24;
    let bottomPadding = -20;
    let totalHeight = headerHeight + validComments.length * (cardHeight + cardGap) + bottomPadding;

    var svg = `<svg viewBox="0 0 700 ${totalHeight}" xmlns="http://www.w3.org/2000/svg" style="display:block;margin-top:16px;width:100%;max-width:700px;height:auto;">
    <rect x="0" y="0" width="700" height="${totalHeight}" rx="18" fill="none" stroke="${color}" stroke-width="0.5" opacity="0.6"/>
    <text x="32" y="44" font-family="system-ui, -apple-system, sans-serif" font-size="24" font-weight="700" fill="${color}" opacity="1">💬 本章说</text>
    <text x="668" y="44" text-anchor="end" font-family="system-ui, -apple-system, sans-serif" font-size="18" font-weight="600" fill="${color}" opacity="0.9">${countText}条评论 ›</text>
    <line x1="28" y1="58" x2="672" y2="58" stroke="${color}" stroke-width="0.3" opacity="0.35"/>`;

    validComments.forEach(function(c, idx) {
        let yPos = 77 + idx * (cardHeight + cardGap);
        let maxCharsPerLine = 23;
        let contentDisplay = c.content;

        if (contentDisplay.length > maxCharsPerLine * 2) {
            contentDisplay = contentDisplay.substring(0, maxCharsPerLine * 2) + '…';
        }

        let hasTwoLines = contentDisplay.length > maxCharsPerLine;
        let line1Text = hasTwoLines ? contentDisplay.substring(0, maxCharsPerLine) : contentDisplay;
        let line2Text = hasTwoLines ? contentDisplay.substring(maxCharsPerLine) : '';

        let likeText = c.likeCount > 999 ? "999+" : String(c.likeCount);
        let likeWidth = likeText.length * 13 + 50;
        let likeX = 668 - likeWidth;

        let avatarColors = ["#e07078", "#6090d0", "#50b878", "#d0a860", "#9060c8"];
        let avatarColor = avatarColors[idx % avatarColors.length];
        let initial = c.userName.charAt(0);

        let cardBg = idx % 2 == 0 ? 'rgba(128,128,128,0.1)' : 'rgba(128,128,128,0.05)';

        svg += `
    <rect x="14" y="${yPos}" width="672" height="${cardHeight}" rx="14" fill="${cardBg}"/>
    <circle cx="50" cy="${yPos + 34}" r="19" fill="${avatarColor}" opacity="0.95"/>
    <text x="50" y="${yPos + 40}" text-anchor="middle" font-family="system-ui, -apple-system, sans-serif" font-size="16" font-weight="700" fill="#ffffff">${initial}</text>
